from hashlib import sha256, md5

class BloomFilter:
    def __init__(self, m_bits, k_hashes):
        self.m = m_bits
        self.k = k_hashes
        self.bits = bytearray((m_bits + 7) // 8)

    def _hashes(self, item):
        b = item.encode('utf-8')
        h1 = int(sha256(b).hexdigest(), 16)
        h2 = int(md5(b).hexdigest(), 16)
        for i in range(self.k):
            yield (h1 + i * h2) % self.m

    def add(self, item):
        for pos in self._hashes(item):
            self.bits[pos // 8] |= 1 << (pos % 8)

    def contains(self, item):
        return all((self.bits[pos // 8] >> (pos % 8)) & 1 for pos in self._hashes(item))

# Example
bf = BloomFilter(m_bits=1_000_000, k_hashes=6)
bf.add('alpha')
print(bf.contains('alpha'))  # likely True
print(bf.contains('omega'))  # likely False
